function adicionarEventoClique(){document.querySelectorAll(".opcoes label").forEach(function(e){e.addEventListener("click",function(){document.querySelectorAll(".opcoes label").forEach(function(e){e.classList.remove("clicked")}),this.classList.add("clicked")})})}function verificarResposta(e,o,t,a){var r=document.getElementById(e).dataset.jaRespondeu;if("true"!==r){var c=document.querySelector("#"+e+' input[type="radio"]:checked'),n=document.querySelector("#"+e+" .retorno"),s=n.querySelector(".explicacao");if(c){n.style.display="block";var i=c.value;if(i===o)s.innerHTML="<span class='bold'>Comentário:</span> <br><br>"+t,c.parentNode.classList.add("opcao-correta");else{var l="";a?(l="A resposta correta é a alternativa "+o.toUpperCase()+".<br><br>",c.parentNode.classList.add("resposta-correta")):(l="Resposta certa: Incorreta.<br><br>",c.parentNode.classList.add("resposta-incorreta")),l+="<span class='bold'>Comentário:</span> <br><br>"+t,s.innerHTML=l,n.style.display="block",c.parentNode.classList.add("opcao-incorreta"),document.querySelector("#"+e+' input[value="'+o+'"]').parentNode.classList.add("opcao-correta");var d=document.getElementById(e);d.classList.add("shake-animation"),document.body.classList.add("shake-animation-active"),setTimeout(function(){document.body.classList.remove("shake-animation-active")},1e3)}document.getElementById(e).dataset.jaRespondeu="true",document.querySelectorAll("#"+e+' input[type="radio"]').forEach(function(e){e.disabled=!0}),document.querySelectorAll("#"+e+" .opcoes label").forEach(function(e){e.removeEventListener("click",adicionarEventoClique),e.style.pointerEvents="none",e.style.cursor="default"})}else alert("Por favor, selecione uma opção.")}else mostrarPopup()}window.onload=function(){adicionarEventoClique()};